        ],
        options: { minAgents: 2 },
      });

      expect(result.consensusAchieved).toBe(true);
    });
  });

  describe('recommendations', () => {
    it('should provide positive recommendation on success', async () => {
      const result = await tool.execute({
        agentStates: [
          { agentId: 'a1', embedding: [1, 0, 0], vote: true },
