/**
 * Category Engine - Functors and Morphisms
 *
 * Implements category theory operations for type-safe transformations:
 * - Morphism application and composition
 * - Natural transformations
 * - Functor mappings
 *
 * Used for agent type transformations and workflow composition.
 */

import type {
  ICategoryEngine,
  Morphism,
  MorphismResult,
  WasmModule
} from '../types.js';

/**
 * CategoryEngine - WASM wrapper for category theory operations
 */
export class CategoryEngine implements ICategoryEngine {
  private wasmModule: WasmModule | null = null;
  private morphismRegistry: Map<string, Morphism> = new Map();
  private functorRegistry: Map<string, (input: unknown) => unknown> = new Map();

  constructor(wasmModule?: WasmModule) {
    this.wasmModule = wasmModule ?? null;
    this.initializeBuiltinFunctors();
  }

  /**
   * Set the WASM module after initialization
   */
  setWasmModule(module: WasmModule): void {
    this.wasmModule = module;
  }

  /**
   * Apply a functor/morphism to transform data
   *
   * @param morphism - Morphism specification
   * @returns MorphismResult with transformed data
   */
  async applyFunctor(morphism: Morphism): Promise<MorphismResult> {
    // Validate morphism
    const valid = this.validateMorphism(
      morphism.data ?? null,
      null,
      morphism.name
    );

    if (!valid) {
      return {
        valid: false,
        result: null,
        naturalTransformation: false
      };
    }

    // Apply the morphism
    const functor = this.functorRegistry.get(morphism.name);
    if (!functor) {
      // Attempt identity morphism
      return {
        valid: true,
        result: morphism.data,
        naturalTransformation: false
      };
    }

    try {
      const result = functor(morphism.data);
      const isNatural = this.isNaturalTransformation(morphism.name);

      return {
        valid: true,
        result,
        naturalTransformation: isNatural
      };
    } catch {
      return {
        valid: false,
        result: null,
        naturalTransformation: false
      };
    }
  }

  /**
   * Compose two morphisms: g . f (apply f then g)
   *
   * @param f - First morphism
   * @param g - Second morphism
   * @returns Composed morphism
   */
  async compose(f: Morphism, g: Morphism): Promise<Morphism> {
    // Verify composability: f.target === g.source
    if (f.target !== g.source) {
      throw new Error(
        `Cannot compose morphisms: ${f.name} (target: ${f.target}) and ${g.name} (source: ${g.source}) - ` +
        `target of first must equal source of second`
      );
    }

    // Create composed morphism
    const composedName = `${g.name} . ${f.name}`;

    // Register the composed functor
    const fFunctor = this.functorRegistry.get(f.name);
    const gFunctor = this.functorRegistry.get(g.name);

    if (fFunctor && gFunctor) {
      this.functorRegistry.set(composedName, (input: unknown) => {
        const intermediate = fFunctor(input);
        return gFunctor(intermediate);
      });
    }

    const composed: Morphism = {
      source: f.source,
      target: g.target,
      name: composedName,
      data: f.data
    };

    this.morphismRegistry.set(composedName, composed);
    return composed;
  }

  /**
   * Validate that a morphism is well-defined
   *
   * @param source - Source object
   * @param target - Target object
   * @param morphism - Morphism name
   * @returns Whether the morphism is valid
   */
  validateMorphism(source: unknown, target: unknown, morphism: string): boolean {
    // Check if morphism is registered
    if (this.functorRegistry.has(morphism)) {
      return true;
    }

    // Check built-in morphisms
    const builtins = [
      'identity', 'map', 'filter', 'reduce', 'flatten',
      'embed', 'project', 'lift', 'lower'
    ];

    if (builtins.includes(morphism)) {
      return true;
    }

    // Check if it's a composition
    if (morphism.includes(' . ')) {
      const parts = morphism.split(' . ');
      return parts.every(part => this.validateMorphism(source, target, part.trim()));
    }

    return false;
  }

  /**
   * Check if a morphism is a natural transformation
   * (commutes with all functors)
   *
   * @param morphism - Morphism name
   * @returns Whether it's a natural transformation
   */
  isNaturalTransformation(morphism: string): boolean {
    // Natural transformations preserve structure
    const naturalMorphisms = [
      'identity', 'map', 'flatten', 'embed', 'project'
    ];

    return naturalMorphisms.includes(morphism);
  }

  /**
   * Register a custom functor
   *
   * @param name - Functor name
   * @param fn - Transformation function
   * @param metadata - Optional metadata
   */
  registerFunctor(
    name: string,
    fn: (input: unknown) => unknown,
    metadata?: { source?: string; target?: string; natural?: boolean }
  ): void {
    this.functorRegistry.set(name, fn);

    if (metadata) {
      this.morphismRegistry.set(name, {
        name,
        source: metadata.source ?? 'Any',
        target: metadata.target ?? 'Any',
        data: metadata
      });
    }
  }

  /**
   * Get registered morphism
   */
  getMorphism(name: string): Morphism | undefined {
    return this.morphismRegistry.get(name);
  }

  /**
   * List all registered functors
   */
  listFunctors(): string[] {
    return Array.from(this.functorRegistry.keys());
  }

  /**
   * Create an identity morphism for a type
   */
  identity(type: string): Morphism {
    return {
      source: type,
      target: type,
      name: `identity_${type}`,
      data: null
    };
  }

  /**
   * Create a lifting morphism (A -> F(A))
   */
  lift<T>(value: T, functorName: string): Morphism {
    return {
      source: typeof value,
      target: `${functorName}<${typeof value}>`,
      name: `lift_${functorName}`,
      data: value
    };
  }

  /**
   * Initialize built-in functors
   */
  private initializeBuiltinFunctors(): void {
    // Identity functor
    this.registerFunctor('identity', (x) => x, {
      source: 'Any',
      target: 'Any',
      natural: true
    });

    // Map functor (for arrays)
    this.registerFunctor('map', (x) => {
      if (Array.isArray(x)) {
        return x.map(item => item);
      }
      return x;
    }, {
      source: 'Array<A>',
      target: 'Array<B>',
      natural: true
    });

    // Filter functor
    this.registerFunctor('filter', (x) => {
      if (Array.isArray(x)) {
        return x.filter(Boolean);
      }
      return x;
    }, {
      source: 'Array<A>',
      target: 'Array<A>',
      natural: false
    });

    // Flatten functor
    this.registerFunctor('flatten', (x) => {
      if (Array.isArray(x)) {
        return x.flat();
      }
      return x;
    }, {
      source: 'Array<Array<A>>',
      target: 'Array<A>',
      natural: true
    });

    // Embed functor (scalar to array)
    this.registerFunctor('embed', (x) => {
      if (!Array.isArray(x)) {
        return [x];
      }
      return x;
    }, {
      source: 'A',
      target: 'Array<A>',
      natural: true
    });

    // Project functor (extract first)
    this.registerFunctor('project', (x) => {
      if (Array.isArray(x) && x.length > 0) {
        return x[0];
      }
      return x;
    }, {
      source: 'Array<A>',
      target: 'A',
      natural: true
    });

    // JSON encode functor
    this.registerFunctor('json_encode', (x) => JSON.stringify(x), {
      source: 'Any',
      target: 'String',
      natural: false
    });

    // JSON decode functor
    this.registerFunctor('json_decode', (x) => {
      if (typeof x === 'string') {
        try {
          return JSON.parse(x);
        } catch {
          return x;
        }
      }
      return x;
    }, {
      source: 'String',
      target: 'Any',
      natural: false
    });

    // Vector normalization functor
    this.registerFunctor('normalize', (x) => {
      if (x instanceof Float32Array || Array.isArray(x)) {
        const arr = Array.isArray(x) ? x : Array.from(x);
        const norm = Math.sqrt(arr.reduce((sum, v) => sum + v * v, 0));
        if (norm === 0) return x;
        return arr.map(v => v / norm);
      }
      return x;
    }, {
      source: 'Vector',
      target: 'UnitVector',
      natural: false
    });

    // Agent state transformation functor
    this.registerFunctor('agent_transform', (x) => {
      if (typeof x === 'object' && x !== null && 'state' in x) {
        return {
          ...(x as Record<string, unknown>),
          transformed: true,
          timestamp: Date.now()
        };
      }
      return x;
    }, {
      source: 'AgentState',
      target: 'AgentState',
      natural: false
    });

    // Memory entry transformation
    this.registerFunctor('memory_transform', (x) => {
      if (typeof x === 'object' && x !== null && 'embedding' in x) {
        return {
          ...(x as Record<string, unknown>),
          validated: true
        };
      }
      return x;
    }, {
      source: 'MemoryEntry',
      target: 'ValidatedMemoryEntry',
      natural: false
    });
  }
}

/**
 * Causal Engine - Do-Calculus Inference
 *
 * Implements causal inference using Pearl's do-calculus.
 * Supports interventional queries, confounder identification,
 * and backdoor path analysis.
 *
 * Based on: https://arxiv.org/abs/1305.5506 (Do-Calculus)
 */

import type {
  ICausalEngine,
  CausalResult,
  CausalEffect,
  CausalGraph,
  Intervention,
  WasmModule
} from '../types.js';

/**
 * CausalEngine - WASM wrapper for causal inference operations
 */
export class CausalEngine implements ICausalEngine {
  private wasmModule: WasmModule | null = null;
  private readonly significanceThreshold = 0.1;

  constructor(wasmModule?: WasmModule) {
    this.wasmModule = wasmModule ?? null;
  }

  /**
   * Set the WASM module after initialization
   */
  setWasmModule(module: WasmModule): void {
    this.wasmModule = module;
  }

  /**
   * Perform causal inference using do-calculus
   *
   * @param intervention - Intervention specification
   * @returns CausalResult with effect estimation
   */
  async infer(intervention: Intervention): Promise<CausalResult> {
    const { treatment, outcome, graph } = intervention;

    // Identify confounders using backdoor criterion
    const confounders = this.identifyConfounders(graph, treatment, outcome);

    // Find all backdoor paths
    const backdoorPaths = this.findBackdoorPaths(graph, treatment, outcome);

    // Check if intervention is valid (all backdoor paths blocked)
    const interventionValid = this.validateIntervention(graph, treatment, confounders);

    // Estimate causal effect
    const effect = await this.computeDoCalculus(graph, treatment, outcome);

    return {
      effect: effect.value,
      confounders,
      interventionValid,
      backdoorPaths
    };
  }

  /**
   * Compute causal effect using do-calculus
   * P(Y | do(X)) estimation
   *
   * @param graph - Causal graph
   * @param treatment - Treatment variable
   * @param outcome - Outcome variable
   * @returns CausalEffect with confidence
   */
  async computeDoCalculus(
    graph: CausalGraph,
    treatment: string,
    outcome: string
  ): Promise<CausalEffect> {
    if (this.wasmModule) {
      // Convert graph to adjacency matrix for WASM
      const { adjMatrix, nodeIndex } = this.graphToAdjMatrix(graph);
      const treatmentIdx = nodeIndex.get(treatment);
      const outcomeIdx = nodeIndex.get(outcome);

      if (treatmentIdx === undefined || outcomeIdx === undefined) {
        return this.createCausalEffect(0, 0);
      }

      const effect = this.wasmModule.causal_estimate_effect(
        treatmentIdx,
        outcomeIdx,
        adjMatrix,
        graph.nodes.length
      );

      // Confidence based on graph structure
      const confidence = this.computeConfidence(graph, treatment, outcome);
      return this.createCausalEffect(effect, confidence);
    }

    // Pure JS implementation
    return this.computeEffectJS(graph, treatment, outcome);
  }

  /**
   * Identify confounders between treatment and outcome
   *
   * @param graph - Causal graph
   * @param treatment - Treatment variable
   * @param outcome - Outcome variable
   * @returns Array of confounder variable names
   */
  identifyConfounders(
    graph: CausalGraph,
    treatment: string,
    outcome: string
  ): string[] {
    const confounders: string[] = [];
    const treatmentParents = this.getParents(graph, treatment);
    const outcomeAncestors = this.getAncestors(graph, outcome);

    // A confounder is a common cause of treatment and outcome
    for (const parent of treatmentParents) {
      if (outcomeAncestors.has(parent) ||
          this.hasPathTo(graph, parent, outcome, new Set([treatment]))) {
        confounders.push(parent);
      }
    }

    // Also check for any node that causes both
    for (const node of graph.nodes) {
      if (node === treatment || node === outcome) continue;

      const causesT = this.hasPathTo(graph, node, treatment, new Set());
      const causesO = this.hasPathTo(graph, node, outcome, new Set([treatment]));

      if (causesT && causesO && !confounders.includes(node)) {
        confounders.push(node);
      }
    }

    return confounders;
  }

  /**
   * Find all backdoor paths from treatment to outcome
   *
   * @param graph - Causal graph
   * @param treatment - Treatment variable
   * @param outcome - Outcome variable
   * @returns Array of paths (each path is array of node names)
   */
  findBackdoorPaths(
    graph: CausalGraph,
    treatment: string,
    outcome: string
  ): string[][] {
    const backdoorPaths: string[][] = [];
    const treatmentParents = this.getParents(graph, treatment);

    // Find all paths from parents of treatment to outcome
    for (const parent of treatmentParents) {
      const paths = this.findAllPaths(graph, parent, outcome, new Set([treatment]));
      for (const path of paths) {
        backdoorPaths.push([treatment, ...path]);
      }
    }

    return backdoorPaths;
  }

  /**
   * Create CausalEffect value object
   */
  createCausalEffect(value: number, confidence: number): CausalEffect {
    const clampedConfidence = Math.max(0, Math.min(1, confidence));

    let direction: 'positive' | 'negative' | 'neutral';
    if (value > this.significanceThreshold) {
      direction = 'positive';
    } else if (value < -this.significanceThreshold) {
      direction = 'negative';
    } else {
      direction = 'neutral';
    }

    return {
      value,
      confidence: clampedConfidence,
      significant: Math.abs(value) > this.significanceThreshold && clampedConfidence > 0.8,
      direction
    };
  }

  /**
   * Validate if an intervention is valid (backdoor criterion satisfied)
   */
  private validateIntervention(
    graph: CausalGraph,
    treatment: string,
    confounders: string[]
  ): boolean {
    // Intervention is valid if we can block all confounding paths
    // by conditioning on a sufficient set

    // Check if confounders form an adjustment set
    // (no descendant of treatment that is also an ancestor of outcome)
    const treatmentDescendants = this.getDescendants(graph, treatment);

    for (const confounder of confounders) {
      if (treatmentDescendants.has(confounder)) {
        // Confounder is a descendant of treatment - invalid adjustment
        return false;
      }
    }

    return true;
  }

  /**
   * Pure JS implementation of causal effect estimation
   */
  private async computeEffectJS(
    graph: CausalGraph,
    treatment: string,
    outcome: string
  ): Promise<CausalEffect> {
    // Check if there's a direct path from treatment to outcome
    const hasDirect = this.hasDirectEdge(graph, treatment, outcome);

    // Check for indirect paths
    const indirectPaths = this.findAllPaths(graph, treatment, outcome, new Set());

    // Compute effect based on path structure
    let effect = 0;
    if (hasDirect) {
      effect += 0.5; // Direct effect contribution
    }

    // Indirect effects (simplified - each path contributes)
    effect += Math.min(indirectPaths.length * 0.1, 0.5);

    // Adjust for confounders
    const confounders = this.identifyConfounders(graph, treatment, outcome);
    const confoundingBias = confounders.length * 0.1;
    effect = Math.max(0, effect - confoundingBias);

    const confidence = this.computeConfidence(graph, treatment, outcome);
    return this.createCausalEffect(effect, confidence);
  }

  /**
   * Compute confidence based on graph structure
   */
  private computeConfidence(
    graph: CausalGraph,
    treatment: string,
    outcome: string
  ): number {
    // Higher confidence when:
    // 1. Direct connection exists
    // 2. Fewer confounders
    // 3. Shorter paths

    let confidence = 0.5;

    if (this.hasDirectEdge(graph, treatment, outcome)) {
      confidence += 0.3;
    }

    const confounders = this.identifyConfounders(graph, treatment, outcome);
    confidence -= confounders.length * 0.1;

    const paths = this.findAllPaths(graph, treatment, outcome, new Set());
    if (paths.length > 0) {
      const avgPathLength = paths.reduce((sum, p) => sum + p.length, 0) / paths.length;
      confidence += Math.max(0, 0.2 - avgPathLength * 0.05);
    }

    return Math.max(0, Math.min(1, confidence));
  }

  /**
   * Convert graph to adjacency matrix
   */
  private graphToAdjMatrix(graph: CausalGraph): {
    adjMatrix: Float32Array;
    nodeIndex: Map<string, number>;
  } {
    const n = graph.nodes.length;
    const adjMatrix = new Float32Array(n * n);
    const nodeIndex = new Map<string, number>();

    graph.nodes.forEach((node, idx) => {
      nodeIndex.set(node, idx);
    });

    for (const [from, to] of graph.edges) {
      const fromIdx = nodeIndex.get(from);
      const toIdx = nodeIndex.get(to);
      if (fromIdx !== undefined && toIdx !== undefined) {
        adjMatrix[fromIdx * n + toIdx] = 1;
      }
    }

    return { adjMatrix, nodeIndex };
  }

  /**
   * Get parent nodes (direct causes)
   */
  private getParents(graph: CausalGraph, node: string): string[] {
    return graph.edges
      .filter(([, to]) => to === node)
      .map(([from]) => from);
  }

  /**
   * Get ancestors (all causes)
   */
  private getAncestors(graph: CausalGraph, node: string): Set<string> {
    const ancestors = new Set<string>();
    const queue = this.getParents(graph, node);

    while (queue.length > 0) {
      const current = queue.shift()!;
      if (!ancestors.has(current)) {
        ancestors.add(current);
        queue.push(...this.getParents(graph, current));
      }
    }

    return ancestors;
  }

  /**
   * Get descendants (all effects)
   */
  private getDescendants(graph: CausalGraph, node: string): Set<string> {
    const descendants = new Set<string>();
    const children = graph.edges
      .filter(([from]) => from === node)
      .map(([, to]) => to);

    const queue = [...children];

    while (queue.length > 0) {
      const current = queue.shift()!;
      if (!descendants.has(current)) {
        descendants.add(current);
        const nextChildren = graph.edges
          .filter(([from]) => from === current)
          .map(([, to]) => to);
        queue.push(...nextChildren);
      }
    }

    return descendants;
  }

  /**
   * Check if there's a direct edge from source to target
   */
  private hasDirectEdge(graph: CausalGraph, source: string, target: string): boolean {
    return graph.edges.some(([from, to]) => from === source && to === target);
  }

  /**
   * Check if there's a path from source to target
   */
  private hasPathTo(graph: CausalGraph, source: string, target: string, blocked: Set<string>): boolean {
    if (source === target) return true;

    const visited = new Set<string>(blocked);
    const queue = [source];

    while (queue.length > 0) {
      const current = queue.shift()!;
      if (visited.has(current)) continue;
      visited.add(current);

      const children = graph.edges
        .filter(([from]) => from === current)
        .map(([, to]) => to);

      for (const child of children) {
        if (child === target) return true;
        if (!visited.has(child)) {
          queue.push(child);
        }
      }
    }

    return false;
  }

  /**
   * Find all paths from source to target
   */
  private findAllPaths(
    graph: CausalGraph,
    source: string,
    target: string,
    blocked: Set<string>,
    currentPath: string[] = [],
    allPaths: string[][] = []
  ): string[][] {
    if (blocked.has(source)) return allPaths;

    const newPath = [...currentPath, source];

    if (source === target) {
      allPaths.push(newPath);
      return allPaths;
    }

    const children = graph.edges
      .filter(([from]) => from === source)
      .map(([, to]) => to);

    const newBlocked = new Set(blocked);
    newBlocked.add(source);

    for (const child of children) {
      if (!blocked.has(child) && !currentPath.includes(child)) {
        this.findAllPaths(graph, child, target, newBlocked, newPath, allPaths);
      }
    }

    return allPaths;
  }
}

/**
 * Cohomology Engine - Sheaf Laplacian Coherence
 *
 * Implements coherence checking using sheaf cohomology and Laplacian energy.
 * Energy 0 = fully coherent, Energy 1 = fully contradictory.
 *
 * Based on: https://arxiv.org/abs/1808.04718 (Sheaf Laplacian Theory)
 */

import type {
  ICohomologyEngine,
  CoherenceResult,
  CoherenceEnergy,
  Sheaf,
  WasmModule
} from '../types.js';

/**
 * CohomologyEngine - WASM wrapper for sheaf Laplacian coherence checking
 */
export class CohomologyEngine implements ICohomologyEngine {
  private wasmModule: WasmModule | null = null;
  private readonly coherenceThreshold = 0.3;
  private readonly contradictionThreshold = 0.7;

  constructor(wasmModule?: WasmModule) {
    this.wasmModule = wasmModule ?? null;
  }

  /**
   * Set the WASM module after initialization
   */
  setWasmModule(module: WasmModule): void {
    this.wasmModule = module;
  }

  /**
   * Check coherence of a set of vectors using Sheaf Laplacian energy
   *
   * @param vectors - Array of embedding vectors to check
   * @returns CoherenceResult with energy and violation details
   */
  async checkCoherence(vectors: Float32Array[]): Promise<CoherenceResult> {
    if (vectors.length === 0) {
      return {
        coherent: true,
        energy: 0,
        violations: [],
        confidence: 1
      };
    }

    if (vectors.length === 1) {
      return {
        coherent: true,
        energy: 0,
        violations: [],
        confidence: 1
      };
    }

    const energy = await this.computeSheafLaplacianEnergy(vectors);
    const violations = await this.detectContradictions(vectors);

    return {
      coherent: energy < this.coherenceThreshold,
      energy,
      violations,
      confidence: 1 - energy
    };
  }

  /**
   * Compute Sheaf Laplacian energy for coherence measurement
   *
   * @param sheaf - Sheaf structure with vertices, edges, and restrictions
   * @returns Energy value [0, 1]
   */
  async computeLaplacianEnergy(sheaf: Sheaf): Promise<number> {
    // Convert sheaf to vector representation
    const vectors: Float32Array[] = [];
    for (const restriction of sheaf.restrictions.values()) {
      vectors.push(restriction);
    }

    if (vectors.length === 0) {
      return 0;
    }

    return this.computeSheafLaplacianEnergy(vectors);
  }

  /**
   * Detect contradictions in a set of vectors
   *
   * @param vectors - Embedding vectors to analyze
   * @returns Array of violation descriptions
   */
  async detectContradictions(vectors: Float32Array[]): Promise<string[]> {
    if (vectors.length < 2) {
      return [];
    }

    const violations: string[] = [];

    if (this.wasmModule) {
      // Use WASM for detection
      const { flattened, dims } = this.flattenVectors(vectors);
      const resultPtr = this.wasmModule.cohomology_detect_contradictions(flattened, dims);

      // Parse WASM result - returns indices of contradicting pairs
      const numPairs = resultPtr[0];
      for (let i = 0; i < numPairs; i++) {
        const idx1 = resultPtr[1 + i * 2];
        const idx2 = resultPtr[2 + i * 2];
        violations.push(`Contradiction between vectors ${idx1} and ${idx2}`);
      }
    } else {
      // Pure JS fallback - pairwise similarity check
      for (let i = 0; i < vectors.length; i++) {
        for (let j = i + 1; j < vectors.length; j++) {
          const vecI = vectors[i];
          const vecJ = vectors[j];
          if (!vecI || !vecJ) continue;
          const similarity = this.cosineSimilarity(vecI, vecJ);

          // Highly dissimilar vectors (negative similarity) indicate contradiction
          if (similarity < -0.5) {
            violations.push(`Contradiction between vectors ${i} and ${j} (similarity: ${similarity.toFixed(3)})`);
          }
        }
      }
    }

    return violations;
  }

  /**
   * Create CoherenceEnergy value object from raw energy
   */
  createCoherenceEnergy(value: number): CoherenceEnergy {
    const clampedValue = Math.max(0, Math.min(1, value));

    let level: 'coherent' | 'warning' | 'contradictory';
    if (clampedValue < this.coherenceThreshold) {
      level = 'coherent';
    } else if (clampedValue < this.contradictionThreshold) {
      level = 'warning';
    } else {
      level = 'contradictory';
    }

    return {
      value: clampedValue,
      coherent: clampedValue < this.coherenceThreshold,
      confidence: 1 - clampedValue,
      level
    };
  }

  /**
   * Internal: Compute Sheaf Laplacian energy from vectors
   */
  private async computeSheafLaplacianEnergy(vectors: Float32Array[]): Promise<number> {
    if (this.wasmModule) {
      // Use WASM module for computation
      const { flattened, dims } = this.flattenVectors(vectors);
      return this.wasmModule.cohomology_compute_energy(flattened, dims);
    }

    // Pure JS fallback implementation
    return this.computeEnergyJS(vectors);
  }

  /**
   * Pure JS implementation of Sheaf Laplacian energy
   * Uses the graph Laplacian approximation
   */
  private computeEnergyJS(vectors: Float32Array[]): number {
    const n = vectors.length;
    if (n < 2) return 0;

    // Build similarity matrix
    const similarities: number[][] = [];
    for (let i = 0; i < n; i++) {
      similarities[i] = [];
      for (let j = 0; j < n; j++) {
        const vecI = vectors[i];
        const vecJ = vectors[j];
        if (!vecI || !vecJ) {
          similarities[i]![j] = 0;
        } else {
          similarities[i]![j] = i === j ? 0 : this.cosineSimilarity(vecI, vecJ);
        }
      }
    }

    // Compute Laplacian energy as sum of squared differences weighted by similarity
    let energy = 0;
    let totalWeight = 0;

    for (let i = 0; i < n; i++) {
      for (let j = i + 1; j < n; j++) {
        const simRow = similarities[i];
        const simVal = simRow?.[j] ?? 0;
        const weight = Math.max(0, 1 - simVal); // Dissimilarity weight
        const vecI = vectors[i];
        const vecJ = vectors[j];
        if (!vecI || !vecJ) continue;
        const diff = this.vectorDifference(vecI, vecJ);
        const diffNorm = this.vectorNorm(diff);

        energy += weight * diffNorm * diffNorm;
        totalWeight += weight;
      }
    }

    // Normalize to [0, 1]
    if (totalWeight === 0) return 0;
    const normalizedEnergy = energy / totalWeight;

    // Apply sigmoid to map to [0, 1]
    return 1 / (1 + Math.exp(-normalizedEnergy + 2));
  }

  /**
   * Compute cosine similarity between two vectors
   */
  private cosineSimilarity(a: Float32Array, b: Float32Array): number {
    if (a.length !== b.length) {
      throw new Error('Vectors must have the same dimension');
    }

    let dotProduct = 0;
    let normA = 0;
    let normB = 0;

    for (let i = 0; i < a.length; i++) {
      const ai = a[i] ?? 0;
      const bi = b[i] ?? 0;
      dotProduct += ai * bi;
      normA += ai * ai;
      normB += bi * bi;
    }

    const denominator = Math.sqrt(normA) * Math.sqrt(normB);
    if (denominator === 0) return 0;

    return dotProduct / denominator;
  }

  /**
   * Compute difference between two vectors
   */
  private vectorDifference(a: Float32Array, b: Float32Array): Float32Array {
    const result = new Float32Array(a.length);
    for (let i = 0; i < a.length; i++) {
      result[i] = (a[i] ?? 0) - (b[i] ?? 0);
    }
    return result;
  }

  /**
   * Compute L2 norm of a vector
   */
  private vectorNorm(v: Float32Array): number {
    let sum = 0;
    for (let i = 0; i < v.length; i++) {
      const vi = v[i] ?? 0;
      sum += vi * vi;
    }
    return Math.sqrt(sum);
  }

  /**
   * Flatten array of vectors for WASM
   */
  private flattenVectors(vectors: Float32Array[]): { flattened: Float32Array; dims: Uint32Array } {
    const dims = new Uint32Array(vectors.length);
    let totalSize = 0;

    for (let i = 0; i < vectors.length; i++) {
      const vec = vectors[i];
      if (vec) {
        dims[i] = vec.length;
        totalSize += vec.length;
      }
    }

    const flattened = new Float32Array(totalSize);
    let offset = 0;

    for (const vector of vectors) {
      flattened.set(vector, offset);
      offset += vector.length;
    }

    return { flattened, dims };
  }
}

/**
 * HoTT Engine - Homotopy Type Theory
 *
 * Implements Homotopy Type Theory operations:
 * - Path equivalence checking
 * - Transport along paths
 * - Type inference and normalization
 * - Proof verification
 *
 * Used for type-level reasoning and proof verification in agent systems.
 */

import type {
  IHottEngine,
  Path,
  TypedValue,
  WasmModule
} from '../types.js';

/**
 * Type representation in HoTT
 */
interface HottType {
  name: string;
  params?: HottType[];
  isPath?: boolean;
  endpoints?: [unknown, unknown];
}

/**
 * HottEngine - WASM wrapper for Homotopy Type Theory operations
 */
export class HottEngine implements IHottEngine {
  private wasmModule: WasmModule | null = null;
  private typeEnvironment: Map<string, HottType> = new Map();
  private proofCache: Map<string, boolean> = new Map();

  constructor(wasmModule?: WasmModule) {
    this.wasmModule = wasmModule ?? null;
    this.initializeBaseTypes();
  }

  /**
   * Set the WASM module after initialization
   */
  setWasmModule(module: WasmModule): void {
    this.wasmModule = module;
  }

  /**
   * Check if two paths are equivalent (homotopic)
   *
   * @param path1 - First path
   * @param path2 - Second path
   * @returns Whether the paths are equivalent
   */
  async checkPathEquivalence(path1: Path, path2: Path): Promise<boolean> {
    // Paths must have same endpoints
    if (!this.equalValues(path1.source, path2.source) ||
        !this.equalValues(path1.target, path2.target)) {
      return false;
    }

    // Same type paths are equivalent if proofs can be transformed
    if (path1.type !== path2.type) {
      return false;
    }

    if (this.wasmModule && path1.proof && path2.proof) {
      // Use WASM for complex path equivalence
      // This would require serialization of proofs
      const proof1Ptr = this.allocString(path1.proof);
      const proof2Ptr = this.allocString(path2.proof);
      const result = this.wasmModule.hott_path_equivalent(proof1Ptr, proof2Ptr);
      this.freeString(proof1Ptr);
      this.freeString(proof2Ptr);
      return result;
    }

    // Pure JS: syntactic equivalence of proofs
    return path1.proof === path2.proof;
  }

  /**
   * Transport a value along a path
   * If P: A -> Type and p: x = y, transport P p: P(x) -> P(y)
   *
   * @param path - Path to transport along
   * @param value - Value to transport
   * @returns Transported value
   */
  async transportAlong(path: Path, value: TypedValue): Promise<TypedValue> {
    // Verify value type matches path source
    if (value.type !== path.type) {
      throw new Error(
        `Type mismatch: value has type ${value.type} but path is in type ${path.type}`
      );
    }

    if (this.wasmModule) {
      // Use WASM for transport
      const pathPtr = this.allocPath(path);
      const valuePtr = this.allocValue(value);
      const resultPtr = this.wasmModule.hott_transport(pathPtr, valuePtr);
      const result = this.readValue(resultPtr);
      this.freePath(pathPtr);
      this.freeValue(valuePtr);
      this.freeValue(resultPtr);
      return result;
    }

    // Pure JS: if source equals value, return target
    if (this.equalValues(path.source, value.value)) {
      return {
        value: path.target,
        type: value.type
      };
    }

    // General transport - apply path transformation
    return this.applyTransport(path, value);
  }

  /**
   * Verify a proof of a proposition
   *
   * @param proposition - Proposition to verify
   * @param proof - Proof term
   * @returns Whether the proof is valid
   */
  async verifyProof(proposition: string, proof: string): Promise<boolean> {
    // Check cache
    const cacheKey = `${proposition}:${proof}`;
    if (this.proofCache.has(cacheKey)) {
      return this.proofCache.get(cacheKey)!;
    }

    if (this.wasmModule) {
      const propPtr = this.allocString(proposition);
      const proofPtr = this.allocString(proof);
      const result = this.wasmModule.hott_verify_proof(propPtr, proofPtr);
      this.freeString(propPtr);
      this.freeString(proofPtr);
      this.proofCache.set(cacheKey, result);
      return result;
    }

    // Pure JS: parse and type-check proof
    const result = this.verifyProofJS(proposition, proof);
    this.proofCache.set(cacheKey, result);
    return result;
  }

  /**
   * Infer the type of a term
   *
   * @param term - Term to type
   * @returns Inferred type
   */
  async inferType(term: string): Promise<string> {
    if (this.wasmModule) {
      const termPtr = this.allocString(term);
      const resultPtr = this.wasmModule.hott_infer_type(termPtr);
      const result = this.readString(resultPtr);
      this.freeString(termPtr);
      return result;
    }

    // Pure JS type inference
    return this.inferTypeJS(term);
  }

  /**
   * Normalize a term to its canonical form
   *
   * @param term - Term to normalize
   * @returns Normalized term
   */
  async normalize(term: string): Promise<string> {
    if (this.wasmModule) {
      const termPtr = this.allocString(term);
      const resultPtr = this.wasmModule.hott_normalize(termPtr);
      const result = this.readString(resultPtr);
      this.freeString(termPtr);
      return result;
    }

    // Pure JS normalization
    return this.normalizeJS(term);
  }

  /**
   * Create a reflexivity path (x = x)
   */
  refl<T>(x: T, type: string): Path {
    return {
      source: x,
      target: x,
      type,
      proof: `refl(${JSON.stringify(x)})`
    };
  }

  /**
   * Create a symmetry path (if p: x = y, then sym(p): y = x)
   */
  sym(path: Path): Path {
    return {
      source: path.target,
      target: path.source,
      type: path.type,
      proof: `sym(${path.proof})`
    };
  }

  /**
   * Create a transitivity path (if p: x = y and q: y = z, then trans(p,q): x = z)
   */
  trans(path1: Path, path2: Path): Path {
    if (!this.equalValues(path1.target, path2.source)) {
      throw new Error('Paths not composable: endpoints do not match');
    }

    return {
      source: path1.source,
      target: path2.target,
      type: path1.type,
      proof: `trans(${path1.proof}, ${path2.proof})`
    };
  }

  /**
   * Apply a function to a path (ap)
   */
  ap<A, B>(f: (a: A) => B, path: Path): Path {
    return {
      source: f(path.source as A),
      target: f(path.target as A),
      type: `${path.type} -> ${typeof f(path.source as A)}`,
      proof: `ap(${f.toString()}, ${path.proof})`
    };
  }

  /**
   * Initialize base types
   */
  private initializeBaseTypes(): void {
    // Unit type
    this.typeEnvironment.set('Unit', { name: 'Unit' });

    // Boolean type
    this.typeEnvironment.set('Bool', { name: 'Bool' });

    // Natural numbers
    this.typeEnvironment.set('Nat', { name: 'Nat' });

    // Function type constructor
    this.typeEnvironment.set('Arrow', {
      name: 'Arrow',
      params: [{ name: 'A' }, { name: 'B' }]
    });

    // Product type constructor
    this.typeEnvironment.set('Prod', {
      name: 'Prod',
      params: [{ name: 'A' }, { name: 'B' }]
    });

    // Sum type constructor
    this.typeEnvironment.set('Sum', {
      name: 'Sum',
      params: [{ name: 'A' }, { name: 'B' }]
    });

    // Identity/Path type
    this.typeEnvironment.set('Id', {
      name: 'Id',
      params: [{ name: 'A' }, { name: 'x' }, { name: 'y' }],
      isPath: true
    });
  }

  /**
   * Check value equality
   */
  private equalValues(a: unknown, b: unknown): boolean {
    if (a === b) return true;

    if (typeof a !== typeof b) return false;

    if (typeof a === 'object' && a !== null && b !== null) {
      return JSON.stringify(a) === JSON.stringify(b);
    }

    return false;
  }

  /**
   * Pure JS proof verification
   */
  private verifyProofJS(proposition: string, proof: string): boolean {
    // Parse proposition
    const propParts = this.parseProposition(proposition);

    // Parse proof
    const proofParts = this.parseProof(proof);

    // Check proof matches proposition
    return this.checkProofMatches(propParts, proofParts);
  }

  /**
   * Parse a proposition string
   */
  private parseProposition(prop: string): { type: string; args: string[] } {
    // Simple parsing: A = B, forall x:T. P, exists x:T. P
    const eqMatch = prop.match(/(.+)\s*=\s*(.+)/);
    if (eqMatch) {
      const arg1 = eqMatch[1]?.trim() ?? '';
      const arg2 = eqMatch[2]?.trim() ?? '';
      return { type: 'eq', args: [arg1, arg2] };
    }

    const forallMatch = prop.match(/forall\s+(\w+)\s*:\s*(\w+)\s*\.\s*(.+)/);
    if (forallMatch) {
      return {
        type: 'forall',
        args: [forallMatch[1] ?? '', forallMatch[2] ?? '', forallMatch[3] ?? '']
      };
    }

    return { type: 'atom', args: [prop] };
  }

  /**
   * Parse a proof term
   */
  private parseProof(proof: string): { constructor: string; args: string[] } {
    const match = proof.match(/^(\w+)\((.*)\)$/);
    if (match) {
      return {
        constructor: match[1] ?? 'var',
        args: this.parseArgs(match[2] ?? '')
      };
    }

    return { constructor: 'var', args: [proof] };
  }

  /**
   * Parse comma-separated arguments
   */
  private parseArgs(args: string): string[] {
    const result: string[] = [];
    let depth = 0;
    let current = '';

    for (const char of args) {
      if (char === '(' || char === '[') depth++;
      if (char === ')' || char === ']') depth--;
      if (char === ',' && depth === 0) {
        result.push(current.trim());
        current = '';
      } else {
        current += char;
      }
    }

    if (current.trim()) {
      result.push(current.trim());
    }

    return result;
  }

  /**
   * Check if proof matches proposition
   */
  private checkProofMatches(
    prop: { type: string; args: string[] },
    proof: { constructor: string; args: string[] }
  ): boolean {
    // Reflexivity proves x = x
    if (proof.constructor === 'refl' && prop.type === 'eq') {
      return prop.args[0] === prop.args[1];
    }

    // Symmetry proves y = x from x = y
    if (proof.constructor === 'sym' && prop.type === 'eq') {
      return true; // Would need to verify inner proof
    }

    // Transitivity proves x = z from x = y and y = z
    if (proof.constructor === 'trans' && prop.type === 'eq') {
      return proof.args.length === 2;
    }

    // Lambda proves forall
    if (proof.constructor === 'lambda' && prop.type === 'forall') {
      return true; // Would need to verify body
    }

    return false;
  }

  /**
   * Pure JS type inference
   */
  private inferTypeJS(term: string): string {
    const parsed = this.parseProof(term);

    switch (parsed.constructor) {
      case 'refl':
        return `Id(${parsed.args[0]}, ${parsed.args[0]}, ${parsed.args[0]})`;

      case 'sym':
        return 'Id'; // Would need to infer from argument

      case 'trans':
        return 'Id'; // Would need to infer from arguments

      case 'lambda':
        return 'Arrow'; // Would need to infer domain and codomain

      case 'pair':
        return 'Prod'; // Would need to infer components

      default:
        return 'Unknown';
    }
  }

  /**
   * Pure JS term normalization
   */
  private normalizeJS(term: string): string {
    // Beta reduction
    let normalized = term;

    // Simplify refl compositions
    normalized = normalized.replace(/trans\(refl\(([^)]+)\),\s*([^)]+)\)/g, '$2');
    normalized = normalized.replace(/trans\(([^)]+),\s*refl\(([^)]+)\)\)/g, '$1');

    // Simplify sym(sym(p)) = p
    normalized = normalized.replace(/sym\(sym\(([^)]+)\)\)/g, '$1');

    return normalized;
  }

  /**
   * Apply transport transformation
   */
  private applyTransport(path: Path, value: TypedValue): TypedValue {
    // For identity paths, transport is identity
    if (this.equalValues(path.source, path.target)) {
      return value;
    }

    // General case: transform value according to path
    // This is a simplified implementation
    const transformedValue = this.substituteInValue(
      value.value,
      path.source,
      path.target
    );

    return {
      value: transformedValue,
      type: value.type
    };
  }

  /**
   * Substitute occurrences in a value
   */
  private substituteInValue(value: unknown, from: unknown, to: unknown): unknown {
    if (this.equalValues(value, from)) {
      return to;
    }

    if (typeof value === 'object' && value !== null) {
      if (Array.isArray(value)) {
        return value.map(v => this.substituteInValue(v, from, to));
      }

      const result: Record<string, unknown> = {};
      for (const [k, v] of Object.entries(value)) {
        result[k] = this.substituteInValue(v, from, to);
      }
      return result;
    }

    return value;
  }

  // WASM memory allocation helpers (stubs for pure JS fallback)
  private allocString(_s: string): number {
    return 0;
  }

  private freeString(_ptr: number): void {}

  private readString(_ptr: number): string {
    return '';
  }

  private allocPath(_path: Path): number {
    return 0;
  }

  private freePath(_ptr: number): void {}

  private allocValue(_value: TypedValue): number {
    return 0;
  }

  private freeValue(_ptr: number): void {}

  private readValue(_ptr: number): TypedValue {
    return { value: null, type: 'Unknown' };
  }
}

/**
 * Quantum Engine - Topology Operations
 *
 * Implements quantum topology computations including:
 * - Betti numbers (topological invariants)
 * - Persistent homology
 * - Simplicial complex analysis
 *
 * Used for analyzing agent relationship graphs and memory topology.
 */

import type {
  IQuantumEngine,
  BettiNumbers,
  PersistenceDiagram,
  PersistencePoint,
  SimplicialComplex,
  Filtration,
  TopologyResult,
  WasmModule
} from '../types.js';

/**
 * QuantumEngine - WASM wrapper for quantum topology operations
 */
export class QuantumEngine implements IQuantumEngine {
  private wasmModule: WasmModule | null = null;

  constructor(wasmModule?: WasmModule) {
    this.wasmModule = wasmModule ?? null;
  }

  /**
   * Set the WASM module after initialization
   */
  setWasmModule(module: WasmModule): void {
    this.wasmModule = module;
  }

  /**
   * Compute Betti numbers for a simplicial complex
   *
   * @param complex - Simplicial complex
   * @returns BettiNumbers value object
   */
  async computeBettiNumbers(complex: SimplicialComplex): Promise<BettiNumbers> {
    if (complex.vertices.length === 0) {
      return this.createBettiNumbers([0]);
    }

    if (this.wasmModule) {
      // Convert complex to point cloud for WASM
      const points = this.complexToPointCloud(complex);
      const n = complex.vertices.length;
      const dim = 3; // Assume 3D embedding
      const maxDim = complex.maxDimension;

      const result = this.wasmModule.quantum_betti_numbers(points, n, dim, maxDim);
      return this.createBettiNumbers(Array.from(result));
    }

    // Pure JS implementation
    return this.computeBettiNumbersJS(complex);
  }

  /**
   * Compute persistence diagram for a filtration
   *
   * @param filtration - Filtration of simplicial complex
   * @returns PersistenceDiagram
   */
  async persistenceDiagram(filtration: Filtration): Promise<PersistenceDiagram> {
    if (filtration.complex.vertices.length === 0) {
      return {
        points: [],
        maxPersistence: 0,
        totalPersistence: 0
      };
    }

    if (this.wasmModule) {
      const points = this.complexToPointCloud(filtration.complex);
      const n = filtration.complex.vertices.length;
      const dim = 3;

      const result = this.wasmModule.quantum_persistence_diagram(points, n, dim);
      return this.parsePersistenceDiagram(result);
    }

    // Pure JS implementation
    return this.computePersistenceDiagramJS(filtration);
  }

  /**
   * Compute number of homology classes
   *
   * @param complex - Simplicial complex
   * @returns Number of homology classes
   */
  async computeHomologyClasses(complex: SimplicialComplex): Promise<number> {
    const betti = await this.computeBettiNumbers(complex);

    // Sum of all Betti numbers
    return betti.values.reduce((sum, b) => sum + b, 0);
  }

  /**
   * Compute full topology result
   *
   * @param points - Point cloud as Float32Array[]
   * @param maxDimension - Maximum dimension for Betti numbers
   * @returns TopologyResult
   */
  async computeTopology(points: Float32Array[], maxDimension: number = 2): Promise<TopologyResult> {
    // Build simplicial complex from points
    const complex = this.buildRipsComplex(points, maxDimension);

    // Build filtration
    const filtration = this.buildFiltration(complex, points);

    // Compute all features
    const bettiNumbers = await this.computeBettiNumbers(complex);
    const persistenceDiagram = await this.persistenceDiagram(filtration);
    const homologyClasses = await this.computeHomologyClasses(complex);

    return {
      bettiNumbers: bettiNumbers.values,
      persistenceDiagram,
      homologyClasses
    };
  }

  /**
   * Create BettiNumbers value object
   */
  createBettiNumbers(values: number[]): BettiNumbers {
    return {
      values: [...values],
      b0: values[0] ?? 0,
      b1: values[1] ?? 0,
      b2: values[2] ?? 0,
      connected: (values[0] ?? 0) === 1,
      hasLoops: (values[1] ?? 0) > 0,
      hasVoids: (values[2] ?? 0) > 0
    };
  }

  /**
   * Pure JS implementation of Betti number computation
   * Uses rank-nullity approach on boundary matrices
   */
  private computeBettiNumbersJS(complex: SimplicialComplex): BettiNumbers {
    const values: number[] = [];

    // b0 = number of connected components
    const b0 = this.countConnectedComponents(complex);
    values.push(b0);

    // b1 = number of loops (1-cycles)
    if (complex.maxDimension >= 1) {
      const b1 = this.computeB1(complex);
      values.push(b1);
    }

    // b2 = number of voids (2-cycles)
    if (complex.maxDimension >= 2) {
      const b2 = this.computeB2(complex);
      values.push(b2);
    }

    return this.createBettiNumbers(values);
  }

  /**
   * Count connected components using union-find
   */
  private countConnectedComponents(complex: SimplicialComplex): number {
    const n = complex.vertices.length;
    if (n === 0) return 0;

    const parent = new Array(n).fill(0).map((_, i) => i);
    const rank = new Array(n).fill(0);

    const find = (x: number): number => {
      const px = parent[x];
      if (px !== undefined && px !== x) {
        parent[x] = find(px);
      }
      return parent[x] ?? x;
    };

    const union = (x: number, y: number): void => {
      const px = find(x);
      const py = find(y);
      if (px === py) return;
      const rpx = rank[px] ?? 0;
      const rpy = rank[py] ?? 0;
      if (rpx < rpy) {
        parent[px] = py;
      } else if (rpx > rpy) {
        parent[py] = px;
      } else {
        parent[py] = px;
        rank[px] = rpx + 1;
      }
    };

    // Get 1-simplices (edges)
    const edges = complex.simplices.filter(s => s.length === 2);

    for (const edge of edges) {
      const v1 = edge[0];
      const v2 = edge[1];
      if (v1 !== undefined && v2 !== undefined) {
        union(v1, v2);
      }
    }

    // Count unique components
    const components = new Set<number>();
    for (let i = 0; i < n; i++) {
      components.add(find(i));
    }

    return components.size;
  }

  /**
   * Compute b1 (number of 1-cycles / loops)
   */
  private computeB1(complex: SimplicialComplex): number {
    const vertices = complex.vertices.length;
    const edges = complex.simplices.filter(s => s.length === 2).length;
    const components = this.countConnectedComponents(complex);

    // Euler characteristic relation: V - E + F = chi
    // b1 = E - V + components (simplified for 2D)
    // This is an approximation - full computation requires boundary matrix ranks

    return Math.max(0, edges - vertices + components);
  }

  /**
   * Compute b2 (number of 2-cycles / voids)
   */
  private computeB2(complex: SimplicialComplex): number {
    const triangles = complex.simplices.filter(s => s.length === 3).length;
    const tetrahedra = complex.simplices.filter(s => s.length === 4).length;

    // Simplified approximation
    // Full computation requires boundary matrix of 3-simplices
    return Math.max(0, triangles - 3 * tetrahedra);
  }

  /**
   * Pure JS implementation of persistence diagram
   */
  private computePersistenceDiagramJS(filtration: Filtration): PersistenceDiagram {
    const points: PersistencePoint[] = [];
    const { complex, values } = filtration;

    // Sort simplices by filtration value
    const sortedSimplices = complex.simplices
      .map((simplex, idx) => ({ simplex, value: values[idx] ?? 0 }))
      .sort((a, b) => a.value - b.value);

    // Track component births and merges
    const n = complex.vertices.length;
    const parent = new Array(n).fill(0).map((_, i) => i);
    const birthTime = new Array(n).fill(0);

    const find = (x: number): number => {
      const px = parent[x];
      if (px !== undefined && px !== x) {
        parent[x] = find(px);
      }
      return parent[x] ?? x;
    };

    for (const { simplex, value } of sortedSimplices) {
      if (simplex.length === 1) {
        // Vertex - birth of component
        const v = simplex[0];
        if (v !== undefined) {
          birthTime[v] = value;
        }
      } else if (simplex.length === 2) {
        // Edge - potential merge
        const v1 = simplex[0];
        const v2 = simplex[1];
        if (v1 === undefined || v2 === undefined) continue;
        const p1 = find(v1);
        const p2 = find(v2);

        if (p1 !== p2) {
          // Merge - older component survives
          const birthP1 = birthTime[p1] ?? 0;
          const birthP2 = birthTime[p2] ?? 0;
          const older = birthP1 <= birthP2 ? p1 : p2;
          const younger = older === p1 ? p2 : p1;

          // Death of younger component
          const birth = birthTime[younger] ?? 0;
          const death = value;

          if (death > birth) {
            points.push({
              birth,
              death,
              persistence: death - birth,
              dimension: 0
            });
          }

          parent[younger] = older;
        } else {
          // Same component - creates a loop (1-cycle born)
          points.push({
            birth: value,
            death: Infinity,
            persistence: Infinity,
            dimension: 1
          });
        }
      }
    }

    // Components that never die
    const components = new Set<number>();
    for (let i = 0; i < n; i++) {
      components.add(find(i));
    }

    for (const comp of components) {
      points.push({
        birth: birthTime[comp] ?? 0,
        death: Infinity,
        persistence: Infinity,
        dimension: 0
      });
    }

    const finitePoints = points.filter(p => p.persistence !== Infinity);
    const maxPersistence = finitePoints.length > 0
      ? Math.max(...finitePoints.map(p => p.persistence))
      : 0;
    const totalPersistence = finitePoints.reduce((sum, p) => sum + p.persistence, 0);

    return {
      points,
      maxPersistence,
      totalPersistence
    };
  }

  /**
   * Parse WASM persistence diagram result
   */
  private parsePersistenceDiagram(result: Float32Array): PersistenceDiagram {
    const points: PersistencePoint[] = [];

    // Format: [numPoints, birth1, death1, dim1, birth2, death2, dim2, ...]
    const numPoints = result[0] ?? 0;

    for (let i = 0; i < numPoints; i++) {
      const birth = result[1 + i * 3] ?? 0;
      const death = result[2 + i * 3] ?? 0;
      const dimension = result[3 + i * 3] ?? 0;

      points.push({
        birth,
        death,
        persistence: death - birth,
        dimension
      });
    }

    const finitePoints = points.filter(p => Number.isFinite(p.persistence));
    const maxPersistence = finitePoints.length > 0
      ? Math.max(...finitePoints.map(p => p.persistence))
      : 0;
    const totalPersistence = finitePoints.reduce((sum, p) => sum + p.persistence, 0);

    return {
      points,
      maxPersistence,
      totalPersistence
    };
  }

  /**
   * Build Vietoris-Rips complex from point cloud
   */
  private buildRipsComplex(points: Float32Array[], maxDimension: number): SimplicialComplex {
    const n = points.length;
    const vertices = Array.from({ length: n }, (_, i) => i);
    const simplices: number[][] = [];

    // Add vertices as 0-simplices
    for (let i = 0; i < n; i++) {
      simplices.push([i]);
    }

    // Compute pairwise distances and add edges
    const threshold = this.computeThreshold(points);

    for (let i = 0; i < n; i++) {
      for (let j = i + 1; j < n; j++) {
        const pi = points[i];
        const pj = points[j];
        if (!pi || !pj) continue;
        const dist = this.euclideanDistance(pi, pj);
        if (dist <= threshold) {
          simplices.push([i, j]);
        }
      }
    }

    // Add triangles (2-simplices) if maxDimension >= 2
    if (maxDimension >= 2) {
      const edges = simplices.filter(s => s.length === 2);
      for (let i = 0; i < n; i++) {
        for (let j = i + 1; j < n; j++) {
          for (let k = j + 1; k < n; k++) {
            // Check if all three edges exist
            const hasIJ = edges.some(e => (e[0] === i && e[1] === j) || (e[0] === j && e[1] === i));
            const hasJK = edges.some(e => (e[0] === j && e[1] === k) || (e[0] === k && e[1] === j));
            const hasIK = edges.some(e => (e[0] === i && e[1] === k) || (e[0] === k && e[1] === i));

            if (hasIJ && hasJK && hasIK) {
              simplices.push([i, j, k]);
            }
          }
        }
      }
    }

    return {
      vertices,
      simplices,
      maxDimension
    };
  }

  /**
   * Build filtration from complex
   */
  private buildFiltration(complex: SimplicialComplex, points: Float32Array[]): Filtration {
    const values: number[] = [];

    for (const simplex of complex.simplices) {
      if (simplex.length === 1) {
        values.push(0); // Vertices appear at time 0
      } else {
        // Edge/face appears when its diameter is reached
        let maxDist = 0;
        for (let i = 0; i < simplex.length; i++) {
          for (let j = i + 1; j < simplex.length; j++) {
            const si = simplex[i];
            const sj = simplex[j];
            if (si === undefined || sj === undefined) continue;
            const pi = points[si];
            const pj = points[sj];
            if (!pi || !pj) continue;
            const dist = this.euclideanDistance(pi, pj);
            maxDist = Math.max(maxDist, dist);
          }
        }
        values.push(maxDist);
      }
    }

    return { complex, values };
  }

  /**
   * Compute threshold for Rips complex
   */
  private computeThreshold(points: Float32Array[]): number {
    if (points.length < 2) return 0;

    // Use median of all pairwise distances
    const distances: number[] = [];
    for (let i = 0; i < points.length; i++) {
      for (let j = i + 1; j < points.length; j++) {
        const pi = points[i];
        const pj = points[j];
        if (!pi || !pj) continue;
        distances.push(this.euclideanDistance(pi, pj));
      }
    }

    distances.sort((a, b) => a - b);
    return distances[Math.floor(distances.length / 2)] ?? 0;
  }

  /**
   * Euclidean distance between two points
   */
  private euclideanDistance(a: Float32Array, b: Float32Array): number {
    let sum = 0;
    const len = Math.min(a.length, b.length);
    for (let i = 0; i < len; i++) {
      const diff = (a[i] ?? 0) - (b[i] ?? 0);
      sum += diff * diff;
    }
    return Math.sqrt(sum);
  }

  /**
   * Convert simplicial complex to point cloud for WASM
   */
  private complexToPointCloud(complex: SimplicialComplex): Float32Array {
    // Simple embedding: use vertex index as coordinate
    const n = complex.vertices.length;
    const dim = 3;
    const points = new Float32Array(n * dim);

    for (let i = 0; i < n; i++) {
      // Create simple embedding based on vertex connectivity
      const edges = complex.simplices
        .filter(s => s.length === 2 && s.includes(i));

      points[i * dim] = i; // x = vertex index
      points[i * dim + 1] = edges.length; // y = degree
      points[i * dim + 2] = 0; // z = 0
    }

    return points;
  }
}

/**
 * Spectral Engine - Stability Analysis
 *
 * Implements spectral graph theory analysis for system stability.
 * Uses eigenvalue decomposition to detect clustering, connectivity,
 * and stability issues in multi-agent systems.
 */

import type {
  ISpectralEngine,
  SpectralResult,
  SpectralGap,
  WasmModule
} from '../types.js';

/**
 * SpectralEngine - WASM wrapper for spectral stability analysis
 */
export class SpectralEngine implements ISpectralEngine {
  private wasmModule: WasmModule | null = null;
  private readonly stabilityThreshold = 0.1;

  constructor(wasmModule?: WasmModule) {
    this.wasmModule = wasmModule ?? null;
  }

  /**
   * Set the WASM module after initialization
   */
  setWasmModule(module: WasmModule): void {
    this.wasmModule = module;
  }

  /**
   * Analyze stability of a system represented as adjacency matrix
   *
   * @param matrix - Adjacency matrix (2D array)
   * @returns SpectralResult with stability metrics
   */
  async analyzeStability(matrix: number[][]): Promise<SpectralResult> {
    const n = matrix.length;
    if (n === 0) {
      return {
        stable: true,
        eigenvalues: [],
        spectralGap: 1,
        stabilityIndex: 1
      };
    }

    // Flatten matrix for WASM
    const flat = new Float32Array(n * n);
    for (let i = 0; i < n; i++) {
      const row = matrix[i];
      if (!row) continue;
      for (let j = 0; j < n; j++) {
        flat[i * n + j] = row[j] ?? 0;
      }
    }

    const eigenvalues = await this.computeEigenvalues(flat);
    const spectralGap = this.computeSpectralGap(eigenvalues);
    const stabilityIndex = this.computeStabilityIndex(eigenvalues);

    return {
      stable: spectralGap > this.stabilityThreshold,
      eigenvalues,
      spectralGap,
      stabilityIndex
    };
  }

  /**
   * Compute eigenvalues of a matrix
   *
   * @param matrix - Square matrix (2D array or flattened Float32Array)
   * @returns Sorted eigenvalues (descending)
   */
  async computeEigenvalues(matrix: number[][] | Float32Array): Promise<number[]> {
    let flat: Float32Array;
    let n: number;

    if (matrix instanceof Float32Array) {
      flat = matrix;
      n = Math.sqrt(matrix.length);
      if (n !== Math.floor(n)) {
        throw new Error('Matrix must be square');
      }
    } else {
      n = matrix.length;
      flat = new Float32Array(n * n);
      for (let i = 0; i < n; i++) {
        const row = matrix[i];
        if (!row) continue;
        for (let j = 0; j < n; j++) {
          flat[i * n + j] = row[j] ?? 0;
        }
      }
    }

    if (n === 0) return [];
    if (n === 1) return [flat[0] ?? 0];

    if (this.wasmModule) {
      // Use WASM for eigenvalue computation
      const result = this.wasmModule.spectral_compute_eigenvalues(flat, n);
      return Array.from(result).sort((a, b) => b - a);
    }

    // Pure JS fallback - power iteration for top eigenvalues
    return this.computeEigenvaluesJS(flat, n);
  }

  /**
   * Compute spectral gap (difference between first and second eigenvalues)
   *
   * @param eigenvalues - Array of eigenvalues
   * @returns Spectral gap value
   */
  computeSpectralGap(eigenvalues: number[]): number {
    if (eigenvalues.length < 2) {
      return 1; // Trivially stable
    }

    const sorted = [...eigenvalues].sort((a, b) => b - a);
    const first = sorted[0] ?? 0;
    const second = sorted[1] ?? 0;
    return Math.abs(first - second);
  }

  /**
   * Compute stability index from eigenvalues
   *
   * @param eigenvalues - Array of eigenvalues
   * @returns Stability index [0, 1]
   */
  computeStabilityIndex(eigenvalues: number[]): number {
    if (eigenvalues.length === 0) return 1;

    if (this.wasmModule) {
      const eigArray = new Float32Array(eigenvalues);
      return this.wasmModule.spectral_stability_index(eigArray);
    }

    // Pure JS implementation
    // Stability index based on eigenvalue distribution
    const sorted = [...eigenvalues].sort((a, b) => b - a);
    const spectralGap = this.computeSpectralGap(sorted);
    const maxEig = Math.abs(sorted[0] ?? 0);

    if (maxEig === 0) return 1;

    // Combine spectral gap with eigenvalue concentration
    const gapRatio = spectralGap / maxEig;

    // Check for negative eigenvalues (instability indicator)
    const negativeCount = sorted.filter(e => e < 0).length;
    const negativePenalty = negativeCount / eigenvalues.length;

    // Stability index: higher is more stable
    const rawIndex = gapRatio * (1 - negativePenalty * 0.5);

    // Normalize to [0, 1]
    return Math.max(0, Math.min(1, rawIndex));
  }

  /**
   * Create SpectralGap value object
   */
  createSpectralGap(eigenvalues: number[]): SpectralGap {
    const value = this.computeSpectralGap(eigenvalues);

    let stabilityLevel: 'stable' | 'marginal' | 'unstable';
    if (value > 0.2) {
      stabilityLevel = 'stable';
    } else if (value > 0.05) {
      stabilityLevel = 'marginal';
    } else {
      stabilityLevel = 'unstable';
    }

    return {
      value,
      stable: value > this.stabilityThreshold,
      stabilityLevel
    };
  }

  /**
   * Build Laplacian matrix from adjacency matrix
   */
  buildLaplacian(adjacency: Float32Array, n: number): Float32Array {
    const laplacian = new Float32Array(n * n);

    // Compute degree matrix and subtract adjacency
    for (let i = 0; i < n; i++) {
      let degree = 0;
      for (let j = 0; j < n; j++) {
        const val = adjacency[i * n + j] ?? 0;
        degree += val;
        laplacian[i * n + j] = -val;
      }
      laplacian[i * n + i] = degree;
    }

    return laplacian;
  }

  /**
   * Pure JS eigenvalue computation using power iteration
   */
  private computeEigenvaluesJS(matrix: Float32Array, n: number): number[] {
    const eigenvalues: number[] = [];
    const workingMatrix = new Float32Array(matrix);
    const maxIterations = 100;
    const tolerance = 1e-6;

    // Compute top k eigenvalues using deflation
    const k = Math.min(n, 10); // Top 10 eigenvalues

    for (let eigenIndex = 0; eigenIndex < k; eigenIndex++) {
      // Power iteration for dominant eigenvalue
      let v: Float32Array<ArrayBufferLike> = new Float32Array(n);
      for (let i = 0; i < n; i++) {
        v[i] = Math.random();
      }
      v = this.normalizeVector(v);

      let eigenvalue = 0;
      for (let iter = 0; iter < maxIterations; iter++) {
        // Multiply matrix by vector
        const Av = this.matrixVectorMultiply(workingMatrix, v, n);

        // Compute Rayleigh quotient
        const newEigenvalue = this.dotProduct(v, Av);

        // Normalize
        v = this.normalizeVector(Av);

        // Check convergence
        if (Math.abs(newEigenvalue - eigenvalue) < tolerance) {
          eigenvalue = newEigenvalue;
          break;
        }
        eigenvalue = newEigenvalue;
      }

      eigenvalues.push(eigenvalue);

      // Deflate matrix: A' = A - lambda * v * v^T
      for (let i = 0; i < n; i++) {
        for (let j = 0; j < n; j++) {
          const vi = v[i] ?? 0;
          const vj = v[j] ?? 0;
          workingMatrix[i * n + j] -= eigenvalue * vi * vj;
        }
      }
    }

    return eigenvalues.sort((a, b) => b - a);
  }

  /**
   * Matrix-vector multiplication
   */
  private matrixVectorMultiply(matrix: Float32Array<ArrayBufferLike>, vector: Float32Array<ArrayBufferLike>, n: number): Float32Array<ArrayBufferLike> {
    const result = new Float32Array(n);
    for (let i = 0; i < n; i++) {
      let sum = 0;
      for (let j = 0; j < n; j++) {
        sum += (matrix[i * n + j] ?? 0) * (vector[j] ?? 0);
      }
      result[i] = sum;
    }
    return result;
  }

  /**
   * Normalize vector to unit length
   */
  private normalizeVector(v: Float32Array<ArrayBufferLike>): Float32Array<ArrayBufferLike> {
    let norm = 0;
    for (let i = 0; i < v.length; i++) {
      const vi = v[i] ?? 0;
      norm += vi * vi;
    }
    norm = Math.sqrt(norm);

    if (norm === 0) return v;

    const result = new Float32Array(v.length);
    for (let i = 0; i < v.length; i++) {
      result[i] = (v[i] ?? 0) / norm;
    }
    return result;
  }

  /**
   * Dot product of two vectors
   */
  private dotProduct(a: Float32Array<ArrayBufferLike>, b: Float32Array<ArrayBufferLike>): number {
    let sum = 0;
    for (let i = 0; i < a.length; i++) {
      sum += (a[i] ?? 0) * (b[i] ?? 0);
    }
    return sum;
  }
}

